mapper.select:
SELECT DISTINCT a.id as assignment_id, asub.session_id, asub.subject_type, asub.subject_id,
-- Student/Group info CASE WHEN asub.subject_type = 'student' THEN su.user_name WHEN asub.subject_type = 'group' THEN sg.group_name ELSE 'Unknown' END as entity_name,
-- Release status from assignment CASE WHEN a.results_released = 1 THEN 'RELEASED' ELSE 'NOT_RELEASED' END as release_status,
-- Final score override info (set to NULL for now until columns are added) NULL as final_score_override_pct, NULL as final_score_override_reason, NULL as final_score_override_at
FROM assignment a JOIN assessment_submission asub ON a.id = asub.assignment_id LEFT JOIN sys_student st ON asub.subject_type = 'student' AND asub.subject_id = st.user_id LEFT JOIN sys_user su ON st.user_id = su.user_id LEFT JOIN sys_group sg ON asub.subject_type = 'group' AND asub.subject_id = sg.group_id
WHERE a.subject_id = #{subjectId} AND a.id = #{assignmentId}
AND asub.session_id = #{sessionId}
AND ( su.user_name LIKE CONCAT('%', #{searchQuery}, '%') OR st.student_number LIKE CONCAT('%', #{searchQuery}, '%') OR sg.group_name LIKE CONCAT('%', #{searchQuery}, '%') OR sg.group_id LIKE CONCAT('%', #{searchQuery}, '%') )
GROUP BY a.id, asub.session_id, asub.subject_type, asub.subject_id, entity_name ORDER BY entity_name
LIMIT #{limit}
OFFSET #{offset}

SELECT COUNT(DISTINCT CONCAT(a.id, '_', asub.session_id, '_', asub.subject_type, '_', asub.subject_id)) FROM assignment a JOIN assessment_submission asub ON a.id = asub.assignment_id LEFT JOIN sys_student st ON asub.subject_type = 'student' AND asub.subject_id = st.user_id LEFT JOIN sys_user su ON st.user_id = su.user_id LEFT JOIN sys_group sg ON asub.subject_type = 'group' AND asub.subject_id = sg.group_id
WHERE a.subject_id = #{subjectId} AND a.id = #{assignmentId}
AND asub.session_id = #{sessionId}
AND ( su.user_name LIKE CONCAT('%', #{searchQuery}, '%') OR st.student_number LIKE CONCAT('%', #{searchQuery}, '%') OR sg.group_name LIKE CONCAT('%', #{searchQuery}, '%') OR sg.group_id LIKE CONCAT('%', #{searchQuery}, '%') )

SELECT * FROM assessment_submission
WHERE assignment_id = #{assignmentId}
AND session_id = #{sessionId}
AND subject_type = #{subjectType}
AND subject_id = #{subjectId}
AND examiner_id = #{examinerId}
LIMIT 1

